// Parts 1 and 2 — SensorData as JSON and as YAML.
//
// Note what is NOT included here: no <nlohmann/json.hpp>, no <yaml-cpp/yaml.h>.
// The libraries are an implementation detail of src/text_formats.cpp; a caller
// sees std::string in, SensorData out. Keep it that way.
//
// DO NOT EDIT this file — implement the functions in src/text_formats.cpp.

#ifndef AIS2203_TEXT_FORMATS_HPP
#define AIS2203_TEXT_FORMATS_HPP

#include "ais2203/parse_error.hpp"
#include "ais2203/sensor_data.hpp"

#include <filesystem>
#include <optional>
#include <string>

namespace ais2203 {

// The whole content of the file, byte for byte — or std::nullopt if the file
// cannot be opened. (A missing file is an expected situation, not an
// exceptional one; hence optional rather than an exception.)
std::optional<std::string> readFile(const std::filesystem::path& path);

// ---- Part 1: text → SensorData -------------------------------------------
//
// Every field is REQUIRED except `temperature`, which may be absent.
// Malformed text, a missing required field or a field of the wrong type must
// all surface as ais2203::ParseError — never as a library exception.
SensorData parseJson(const std::string& text);
SensorData parseYaml(const std::string& text);

// ---- Part 2: SensorData → text -------------------------------------------
//
// Same field names and nesting as data/reading.json and data/reading.yaml.
// `temperature` is left out entirely when the optional is empty. The output
// must survive the round trip EXACTLY: parseJson(toJson(x)) == x, doubles
// included.
std::string toJson(const SensorData& data);
std::string toYaml(const SensorData& data);

} // namespace ais2203

#endif // AIS2203_TEXT_FORMATS_HPP
